 6371 * acos( cos(radians(-0.22)) * cos(radians(last_lat)) * cos(radians(last_lon) - radians(64.14)) +
 sin(radians(-0.22)) * sin(radians(last_lat)) )
 ) AS km
FROM floats ORDER BY km ASC LIMIT 5;

